CREATE TRIGGER axiom_order_settlement_requires_event BEFORE UPDATE OF state ON orders
WHEN NEW.state='settled' AND OLD.state!='settled' AND NOT EXISTS (
 SELECT 1 FROM provider_events e WHERE e.order_id=OLD.id AND e.kind='settlement'
 AND e.amount_minor=OLD.amount_minor AND e.currency=OLD.currency
) BEGIN SELECT RAISE(ABORT,'settlement_evidence_required'); END;

CREATE TRIGGER axiom_refund_settlement_requires_event BEFORE UPDATE OF state ON refund_requests
WHEN NEW.state='settled' AND OLD.state!='settled' AND NOT EXISTS (
 SELECT 1 FROM provider_events e JOIN orders o ON o.id=OLD.order_id
 WHERE e.event_id=NEW.event_id AND e.order_id=OLD.order_id AND e.kind='refund'
 AND e.amount_minor=OLD.amount_minor AND e.currency=o.currency
) BEGIN SELECT RAISE(ABORT,'refund_evidence_required'); END;

CREATE TRIGGER axiom_refund_cumulative_cap BEFORE UPDATE OF state ON refund_requests
WHEN NEW.state='settled' AND OLD.state!='settled' AND (
 (SELECT COALESCE(SUM(r.amount_minor),0) FROM refund_requests r
  WHERE r.order_id=OLD.order_id AND r.state='settled') + OLD.amount_minor >
 (SELECT o.amount_minor FROM orders o WHERE o.id=OLD.order_id)
) BEGIN SELECT RAISE(ABORT,'refund_exceeds_order_amount'); END;

CREATE TRIGGER axiom_credit_event_tenant_guard BEFORE INSERT ON credit_ledger
WHEN NEW.event_id IS NOT NULL AND NOT EXISTS (
 SELECT 1 FROM provider_events pe JOIN orders o ON o.id=pe.order_id
 WHERE pe.event_id=NEW.event_id AND o.tenant_id=NEW.tenant_id
) BEGIN SELECT RAISE(ABORT,'ledger_event_tenant_mismatch'); END;

CREATE TRIGGER axiom_refund_event_order_guard BEFORE UPDATE OF event_id,state ON refund_requests
WHEN NEW.event_id IS NOT NULL AND NOT EXISTS (
 SELECT 1 FROM provider_events pe JOIN orders o ON o.id=pe.order_id
 WHERE pe.event_id=NEW.event_id AND pe.order_id=NEW.order_id
 AND pe.kind='refund' AND pe.amount_minor=NEW.amount_minor AND o.tenant_id=NEW.tenant_id
) BEGIN SELECT RAISE(ABORT,'refund_event_order_mismatch'); END;

CREATE TRIGGER axiom_provider_event_order_economics BEFORE INSERT ON provider_events
WHEN NOT EXISTS (
 SELECT 1 FROM orders o WHERE o.id=NEW.order_id AND o.currency=NEW.currency
 AND ((NEW.kind='settlement' AND NEW.amount_minor=o.amount_minor)
   OR (NEW.kind='refund' AND NEW.amount_minor<=o.amount_minor))
) BEGIN SELECT RAISE(ABORT,'provider_event_order_economics_mismatch'); END;

CREATE TRIGGER axiom_invoice_order_economics BEFORE INSERT ON invoices
WHEN NOT EXISTS (
 SELECT 1 FROM orders o WHERE o.id=NEW.order_id AND o.tenant_id=NEW.tenant_id
 AND o.currency=NEW.currency AND o.amount_minor=NEW.amount_minor
) BEGIN SELECT RAISE(ABORT,'invoice_order_economics_mismatch'); END;

CREATE TRIGGER axiom_order_terminal_state_guard BEFORE UPDATE OF state ON orders
WHEN OLD.state!=NEW.state AND NOT (OLD.state='pending' AND NEW.state IN ('settled','void'))
BEGIN SELECT RAISE(ABORT,'order_terminal_state_immutable'); END;

CREATE TRIGGER axiom_order_catalog_economics BEFORE INSERT ON orders
WHEN NOT EXISTS (
 SELECT 1 FROM price_catalog p WHERE p.id=NEW.price_id
 AND p.currency=NEW.currency AND p.amount_minor=NEW.amount_minor
 AND p.grant_units=NEW.grant_units
) BEGIN SELECT RAISE(ABORT,'order_catalog_economics_mismatch'); END;

CREATE TRIGGER axiom_catalog_purchased_economics_immutable BEFORE UPDATE ON price_catalog
WHEN EXISTS(SELECT 1 FROM orders o WHERE o.price_id=OLD.id) AND (
 OLD.id!=NEW.id OR OLD.name!=NEW.name OR OLD.currency!=NEW.currency
 OR OLD.amount_minor!=NEW.amount_minor OR OLD.grant_units!=NEW.grant_units
 OR OLD.version!=NEW.version
) BEGIN SELECT RAISE(ABORT,'catalog_purchased_economics_immutable'); END;

CREATE TRIGGER axiom_canonical_link_revocation_terminal BEFORE UPDATE OF status ON canonical_customer_links
WHEN OLD.status='revoked' AND NEW.status!='revoked'
BEGIN SELECT RAISE(ABORT,'canonical_link_revocation_terminal'); END;

CREATE TRIGGER customer_idp_flow_replace BEFORE INSERT ON customer_idp_flows_v1
WHEN EXISTS(SELECT 1 FROM customer_idp_flows_v1 WHERE state_hash=NEW.state_hash)
BEGIN SELECT RAISE(ABORT,'idp_flow_replace_denied'); END;

CREATE TRIGGER customer_idp_flow_initial_state BEFORE INSERT ON customer_idp_flows_v1
WHEN NEW.status!='pending' OR NEW.used_at_ms IS NOT NULL
BEGIN SELECT RAISE(ABORT,'idp_flow_initial_state'); END;

CREATE TRIGGER customer_idp_session_requires_claim BEFORE INSERT ON customer_idp_sessions_v1
WHEN NOT EXISTS(SELECT 1 FROM customer_idp_flows_v1 WHERE state_hash=NEW.flow_hash AND status='processing' AND expires_at_ms>NEW.created_at_ms)
BEGIN SELECT RAISE(ABORT,'idp_flow_not_claimed'); END;

CREATE TRIGGER customer_idp_session_initial_state BEFORE INSERT ON customer_idp_sessions_v1
WHEN NEW.status!='active' OR NEW.session_version!=1
BEGIN SELECT RAISE(ABORT,'idp_session_initial_state'); END;

CREATE TRIGGER customer_idp_session_revocation BEFORE UPDATE OF status,session_version ON customer_idp_sessions_v1
WHEN NOT (OLD.status='active' AND NEW.status='revoked' AND NEW.session_version=OLD.session_version+1)
BEGIN SELECT RAISE(ABORT,'idp_session_revocation_terminal'); END;

CREATE TRIGGER customer_idp_session_replace BEFORE INSERT ON customer_idp_sessions_v1
WHEN EXISTS(SELECT 1 FROM customer_idp_sessions_v1 WHERE session_hash=NEW.session_hash OR flow_hash=NEW.flow_hash)
BEGIN SELECT RAISE(ABORT,'idp_session_replace_denied'); END;
